import math

def prime_fib(n: int):
    def is_prime(number):
        if number <= 1:
            return False
        if number <= 3:
            return True
        if number % 2 == 0 or number % 3 == 0:
            return False
        i = 5
        while i * i <= number:
            if number % i == 0 or number % (i + 2) == 0:
                return False
            i += 6
        return True

    def fibonacci_gen():
        a, b = 0, 1
        while True:
            yield a
            a, b = b, a + b

    fib_gen = fibonacci_gen()
    prime_fibonacci_numbers = []

    while len(prime_fibonacci_numbers) < n:
        fib_num = next(fib_gen)
        if is_prime(fib_num):
            prime_fibonacci_numbers.append(fib_num)

    return prime_fibonacci_numbers[-1]
