from sympy import isprime

def prime_fib(n: int):
    def fibonacci():
        a, b = 0, 1
        while True:
            yield b
            a, b = b, a + b

    prime_fib_numbers = (f for f in fibonacci() if isprime(f))
    return next(x for i, x in enumerate(prime_fib_numbers, start=1) if i == n)
