import itertools

def prime_fib(n: int):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def fibonacci():
        a, b = 0, 1
        while True:
            a, b = b, a + b
            yield a

    prime_fibs = (fib_num for fib_num in fibonacci() if is_prime(fib_num))
    return next(itertools.islice(prime_fibs, n - 1, n))
